perl -MFile::Find -e '
my (@all,@internal); find({wanted=>sub{return unless /\.go$/; return if $File::Find::name =~ m{/(?:\.git|vendor)/}; push @all,$File::Find::name; push @internal,$File::Find::name if $File::Find::name =~ m{^\./internal/};},no_chdir=>1}, ".");
sub clean { my($s)=@_; $s =~ s{"(?:\\.|[^"\\])*"}{""}gs; $s =~ s{`[^`]*`}{``}gs; $s =~ s{//[^\n]*}{}g; $s =~ s{/\*.*?\*/}{}gs; return $s; }
my(%decl,%texts); for my $f (@all){open my $h,"<",$f or next; local $/; my $s=<$h>; close $h; $texts{$f}=clean($s);}
for my $f (@internal){my $s=$texts{$f}; while($s =~ /\bfunc\s*(?:\(\s*[^)]*?\*?\s*([A-Za-z_]\w*)\s*\)\s*)?([A-Za-z_]\w*)\s*(?:\[[^\]]*\]\s*)?\(/g){my($r,$n)=($1||"",$2); push @{$decl{$n}},[$f,$r];}}
for my $n (keys %decl){my($sites,$files)=(0,0); for my $f (@all){my $s=$texts{$f}; my $c=()=$s =~ /\b\Q$n\E\s*\(/g; if($c){$sites+=$c;$files++;}} $sites -= scalar(@{$decl{$n}}); $sites=0 if $sites<0; my $ds=join(",",map {$_->[0].($_->[1]?" recv=".$_->[1]:"")} @{$decl{$n}}); print join("\t",$sites,$files,$n,$ds),"\n";}
' | sort -nr -k1,1

