#!/usr/bin/perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $ROOT = '/bench/repo';
my %decls;
my %file_pkg;
my %file_imports;
my %path_to_pkg;
my %fanin;

find({ wanted => sub {
    return unless /\.go$/;
    return unless $File::Find::name =~ m{^$ROOT/internal/};
    parse_declarations($File::Find::name);
}, no_chdir => 1 }, "$ROOT/internal");

find({ wanted => sub {
    return unless /\.go$/;
    parse_imports($File::Find::name);
}, no_chdir => 1 }, $ROOT);

for my $id (keys %decls) {
    $fanin{$id} = { count => 0, sites => [] };
}

find({ wanted => sub {
    return unless /\.go$/;
    count_calls_in_file($File::Find::name);
}, no_chdir => 1 }, $ROOT);

my @sorted = sort {
    $fanin{$b}{count} <=> $fanin{$a}{count}
        || $decls{$a}{name} cmp $decls{$b}{name}
} keys %decls;

print "TOP_FANIN\n";
for my $i (0 .. 19) {
    last unless defined $sorted[$i];
    my $id = $sorted[$i];
    my $d = $decls{$id};
    printf "%d\t%d\t%s\t%s:%d\n", $i+1, $fanin{$id}{count}, symbol_name($d), $d->{file}, $d->{line};
}

if (@sorted) {
    my $id = $sorted[0];
    print "\nEVIDENCE_TOP\n";
    my $d = $decls{$id};
    print symbol_name($d), "\n";
    print "$d->{file}:$d->{line}\n";
    print "distinct_files:", scalar(keys %{{ map { $_->{file} => 1 } @{ $fanin{$id}{sites} } }}), "\n";
    my %by_file;
    for (@{ $fanin{$id}{sites} }) { $by_file{$_->{file}} += $_->{n}; }
    for my $f (sort { $by_file{$b} <=> $by_file{$a} } keys %by_file) {
        print "  $by_file{$f}\t$f\n";
    }
}

sub symbol_name {
    my ($d) = @_;
    return $d->{recv} ? "($d->{recv}).$d->{name}" : "$d->{pkg}.$d->{name}";
}

sub decl_id {
    my ($pkg_path, $recv, $name) = @_;
    return "$pkg_path|" . ($recv // '') . "|$name";
}

sub internal_pkg_path {
    my ($file) = @_;
    $file =~ m{^$ROOT/internal/([^/]+(?:/[^/]+)*)/[^/]+\.go$};
    return "github.com/usememos/memos/internal/$1";
}

sub parse_declarations {
    my ($file) = @_;
    open my $fh, '<', $file or return;
    my @lines = <$fh>; close $fh;
    my $pkg = '';
    for (@lines) { if (/^package\s+(\w+)/) { $pkg = $1; last; } }
    $file_pkg{$file} = $pkg;
    my $pkg_path = internal_pkg_path($file);
    $path_to_pkg{$pkg_path} = $pkg;
    for my $i (0 .. $#lines) {
        my $line = $lines[$i];
        next unless $line =~ /^func\s+/;
        if ($line =~ /^func\s+\(\s*([^)]*)\)\s+([A-Za-z_]\w*)\s*[\(<{]/) {
            my ($recv, $name) = ($1, $2);
            next if $name eq 'init';
            my $recv_type = normalize_recv($recv);
            my $id = decl_id($pkg_path, $recv_type, $name);
            $decls{$id} = { pkg => $pkg, recv => $recv_type, name => $name, file => $file, line => $i+1, pkg_path => $pkg_path };
        } elsif ($line =~ /^func\s+([A-Za-z_]\w*)\s*[\(<{]/) {
            my $name = $1;
            next if $name eq 'init';
            my $id = decl_id($pkg_path, '', $name);
            $decls{$id} = { pkg => $pkg, recv => '', name => $name, file => $file, line => $i+1, pkg_path => $pkg_path };
        }
    }
}

sub normalize_recv {
    my ($recv) = @_;
    $recv =~ s/^\*//;
    $recv =~ s/^[\w.]+\.//;
    $recv =~ s/^\s+|\s+$//g;
    return $recv;
}

sub parse_imports {
    my ($file) = @_;
    open my $fh, '<', $file or return;
    my $content = do { local $/; <$fh> }; close $fh;
    my %imports;
    while ($content =~ /import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/g) {
        if (!defined $1) { add_import(\%imports, '', $2); next; }
        my $block = $1;
        while ($block =~ /(?:^|\n)\s*(?:([_\w]+)\s+)?"([^"]+)"/g) {
            add_import(\%imports, $1 // '', $2);
        }
    }
    $file_imports{$file} = \%imports;
    if ($content =~ /^package\s+(\w+)/m) {
        $file_pkg{$file} = $1 unless exists $file_pkg{$file};
    }
}

sub add_import {
    my ($imports, $alias, $path) = @_;
    $alias = basename($path) if $alias eq '' || $alias eq '.';
    $imports->{$alias} = $path;
}

sub aliases_for_pkg_path {
    my ($file, $pkg_path) = @_;
    my @aliases;
    my $imps = $file_imports{$file} // {};
    for my $alias (keys %$imps) {
        push @aliases, $alias if $imps->{$alias} eq $pkg_path;
    }
    return @aliases;
}

sub is_declaration_line {
    my ($line, $name) = @_;
    return 1 if $line =~ /^func\s+\Q$name\E\s*[\(<{]/;
    return 1 if $line =~ /^func\s+\([^)]*\)\s+\Q$name\E\s*[\(<{]/;
    return 0;
}

sub strip_comments { my ($l) = @_; $l =~ s|//.*||; return $l; }

sub count_calls_in_file {
    my ($file) = @_;
    open my $fh, '<', $file or return;
    my @lines = <$fh>; close $fh;
    my $file_internal_path = '';
    if ($file =~ m{^$ROOT/internal/}) { $file_internal_path = internal_pkg_path($file); }

    for my $id (keys %decls) {
        my $d = $decls{$id};
        my ($name, $pkg_path, $recv) = @{$d}{qw/name pkg_path recv/};
        my @aliases = aliases_for_pkg_path($file, $pkg_path);
        my $same_pkg = ($file_internal_path && $file_internal_path eq $pkg_path);

        for my $i (0 .. $#lines) {
            my $raw = $lines[$i];
            next if is_declaration_line($raw, $name);
            my $line = strip_comments($raw);
            my $n = 0;
            if (!$recv) {
                if ($same_pkg) {
                    $n += () = $line =~ /(?<![A-Za-z0-9_\.])\Q$name\E\s*\(/g;
                }
                for my $alias (@aliases) {
                    $n += () = $line =~ /(?<![A-Za-z0-9_\.])\Q$alias\E\.\Q$name\E\s*\(/g;
                }
            } else {
                next unless $same_pkg || @aliases;
                $n = () = $line =~ /\.\Q$name\E\s*\(/g;
            }
            if ($n > 0) {
                $fanin{$id}{count} += $n;
                push @{ $fanin{$id}{sites} }, { file => $file, line => $i+1, n => $n };
            }
        }
    }
}

