sub count_calls_in_file {
    my ($file, $is_test) = @_;
    open my $fh,'<',$file or return; my @lines=<$fh>; close $fh;
    my $fip = ($file=~m{^$ROOT/internal/}) ? internal_pkg_path($file) : '';
    for my $id (keys %decls) {
        my $d=$decls{$id}; my ($name,$pp,$recv)=@{$d}{qw/name pkg_path recv/};
        my @aliases=aliases_for_pkg_path($file,$pp); my $same=($fip && $fip eq $pp);
        for my $i (0..$#lines) {
            next if is_decl($lines[$i],$name); my $line=strip($lines[$i]); my $n=0;
            if (!$recv) {
                $n += () = $line=~/(?<![A-Za-z0-9_\.])\Q$name\E\s*\(/g if $same;
                for my $a (@aliases) { $n += () = $line=~/(?<![A-Za-z0-9_\.])\Q$a\E\.\Q$name\E\s*\(/g; }
            } else {
                next unless $same || @aliases;
                $n = () = $line=~/\.\Q$name\E\s*\(/g;
            }
            if ($n>0) { $fanin_all{$id}+=$n; $fanin_prod{$id}+=$n unless $is_test; }
        }
    }
}

