#!/usr/bin/perl
use strict;
use warnings;
use File::Basename;

my $ROOT = '/bench/repo';
my @go_files = split /\n/, `find '$ROOT' -name '*.go' 2>/dev/null`;
my @internal_files = grep { m{^$ROOT/internal/} } @go_files;

my (%decls, %file_pkg, %file_imports, %fanin_all, %fanin_prod);

for my $file (@internal_files) { parse_declarations($file); }
for my $file (@go_files) { parse_imports($file); }
for my $id (keys %decls) {
    $fanin_all{$id} = 0;
    $fanin_prod{$id} = 0;
}
for my $file (@go_files) {
    my $is_test = ($file =~ /_test\.go$/);
    count_calls_in_file($file, $is_test);
}

my @sorted_all = sort { $fanin_all{$b} <=> $fanin_all{$a} || $decls{$a}{name} cmp $decls{$b}{name} } keys %decls;
my @sorted_prod = sort { $fanin_prod{$b} <=> $fanin_prod{$a} || $decls{$a}{name} cmp $decls{$b}{name} } keys %decls;

print "TOP_ALL_REPO\n";
for my $i (0 .. 14) {
    my $id = $sorted_all[$i]; last unless defined $id;
    my $d = $decls{$id};
    printf "%d\t%d\t%s\t%s:%d\n", $i+1, $fanin_all{$id}, symbol_name($d), $d->{file}, $d->{line};
}
print "\nTOP_NON_TEST\n";
for my $i (0 .. 14) {
    my $id = $sorted_prod[$i]; last unless defined $id;
    my $d = $decls{$id};
    printf "%d\t%d\t%s\t%s:%d\n", $i+1, $fanin_prod{$id}, symbol_name($d), $d->{file}, $d->{line};
}

# verify winner all-repo
my $win = $sorted_all[0];
my $d = $decls{$win};
print "\nWINNER_ALL:", symbol_name($d), " @ $d->{file}:$d->{line} count=$fanin_all{$win}\n";
print "WINNER_PROD count=$fanin_prod{$win}\n";

sub symbol_name {
    my ($d) = @_;
    return $d->{recv} ? "($d->{recv}).$d->{name}" : "$d->{pkg}.$d->{name}";
}
sub decl_id { my ($p,$r,$n)=@_; return "$p|".($r//'' )."|$n"; }
sub internal_pkg_path { my ($f)=@_; $f=~m{^$ROOT/internal/([^/]+(?:/[^/]+)*)/[^/]+\.go$}; return "github.com/usememos/memos/internal/$1"; }

sub parse_declarations {
    my ($file) = @_;
    open my $fh, '<', $file or return; my @lines = <$fh>; close $fh;
    my $pkg = ''; for (@lines) { if (/^package\s+(\w+)/) { $pkg = $1; last; } }
    $file_pkg{$file} = $pkg; my $pkg_path = internal_pkg_path($file);
    for my $i (0 .. $#lines) {
        my $line = $lines[$i]; next unless $line =~ /^func\s+/;
        if ($line =~ /^func\s+\(\s*([^)]*)\)\s+([A-Za-z_]\w*)\s*[\(<{]/) {
            my ($recv,$name)=($1,$2); next if $name eq 'init';
            my $id = decl_id($pkg_path, normalize_recv($recv), $name);
            $decls{$id} = { pkg=>$pkg, recv=>normalize_recv($recv), name=>$name, file=>$file, line=>$i+1, pkg_path=>$pkg_path };
        } elsif ($line =~ /^func\s+([A-Za-z_]\w*)\s*[\(<{]/) {
            my $name=$1; next if $name eq 'init';
            my $id = decl_id($pkg_path, '', $name);
            $decls{$id} = { pkg=>$pkg, recv=>'', name=>$name, file=>$file, line=>$i+1, pkg_path=>$pkg_path };
        }
    }
}
sub normalize_recv { my ($r)=@_; $r=~s/^\*//; $r=~s/^[\w.]+\.//; $r=~s/^\s+|\s+$//g; return $r; }
sub parse_imports {
    my ($file) = @_; open my $fh,'<',$file or return; my $c=do{local $/;<$fh>}; close $fh; my %imports;
    while ($c =~ /import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/g) {
        if (!defined $1) { add_import(\%imports,'',$2); next; }
        while ($1 =~ /(?:^|\n)\s*(?:([_\w]+)\s+)?"([^"]+)"/g) { add_import(\%imports,$1//'',$2); }
    }
    $file_imports{$file}=\%imports; if ($c=~/^package\s+(\w+)/m) { $file_pkg{$file}=$1 unless exists $file_pkg{$file}; }
}
sub add_import { my ($i,$a,$p)=@_; $a=basename($p) if $a eq ''||$a eq '.'; $i->{$a}=$p; }
sub aliases_for_pkg_path { my ($f,$pp)=@_; my @aliases; my $im=$file_imports{$f}//{}; push @aliases,$_) for grep { $im->{$_} eq $pp } keys %$im; return @aliases; }
sub is_decl { my ($l,$n)=@_; return 1 if $l=~/^func\s+\Q$n\E\s*[\(<{]/; return 1 if $l=~/^func\s+\([^)]*\)\s+\Q$n\E\s*[\(<{]/; 0; }
sub strip_comments { my ($line)=@_; $line=~s|//.*||; return $line; }

sub count_calls_in_file {
    my ($file, $is_test) = @_;
    open my $fh,'<',$file or return; my @lines=<$fh>; close $fh;
    my $fip = ($file=~m{^$ROOT/internal/}) ? internal_pkg_path($file) : '';
    for my $id (keys %decls) {
        my $d=$decls{$id}; my ($name,$pp,$recv)=@{$d}{qw/name pkg_path recv/};
        my @aliases=aliases_for_pkg_path($file,$pp); my $same=($fip && $fip eq $pp);
        for my $i (0..$#lines) {
            next if is_decl($lines[$i],$name); my $line=strip_comments($lines[$i]); my $n=0;
            if (!$recv) {
                $n += () = $line=~/(?<![A-Za-z0-9_\.])\Q$name\E\s*\(/g if $same;
                for my $alias (@aliases) { $n += () = $line=~/(?<![A-Za-z0-9_\.])\Q$alias\E\.\Q$name\E\s*\(/g; }
            } else {
                next unless $same || @aliases;
                $n = () = $line=~/\.\Q$name\E\s*\(/g;
            }
            if ($n>0) { $fanin_all{$id}+=$n; $fanin_prod{$id}+=$n unless $is_test; }
        }
    }
}

